#!/usr/bin/env node
'use strict';

/**
 * scripts/stamp-checklist.js
 *
 * WHAT THIS DOES
 * Draws the CVsprings brandmark onto page 1 of the EU AI Act checklist PDF
 * (assets/CVsprings-EU-AI-Act-checklist.pdf), top-right, 28pt.
 *
 * WHY IT EXISTS — AND WHEN YOU MUST RE-RUN IT
 * That PDF is a pre-built binary. Its Producer metadata reads "ReportLab PDF
 * Library": it is generated by a Python script that is NOT in this repo and was
 * not found on the machine it was committed from. The mark is therefore not
 * part of the document's own design — it is stamped on afterwards, by this
 * script.
 *
 *   ==> ANY REGENERATION FROM THAT REPORTLAB SOURCE DROPS THE MARK.  <==
 *   ==> Re-run this script afterwards, or the checklist ships unbranded. <==
 *
 * Nothing detects the loss: no test covers a binary asset's contents, and the
 * file still serves, still renders, and still looks plausible without it. See
 * assets/README.md, which is where this is tracked.
 *
 * The durable fix is to draw the mark inside the ReportLab script instead. If
 * that source resurfaces, do that and delete this file.
 *
 * PDF-LIB IS NOT A DEPENDENCY OF THIS PROJECT and must not become one. Install
 * it transiently, outside the repo, and point PDF_LIB_PATH at it:
 *
 *   mkdir -p /tmp/pdftools && (cd /tmp/pdftools && npm init -y >/dev/null && npm i pdf-lib)
 *   PDF_LIB_PATH=/tmp/pdftools/node_modules/pdf-lib node scripts/stamp-checklist.js
 *
 * USAGE
 *   node scripts/stamp-checklist.js                 # stamp in place
 *   node scripts/stamp-checklist.js --out FILE.pdf  # preview, leaves the served file alone
 *   node scripts/stamp-checklist.js --mark M.png    # supply your own PNG instead of rasterising
 *   node scripts/stamp-checklist.js --force         # stamp even if already stamped (see below)
 *
 * By default the mark is rasterised on the fly from public/brandmark.svg — the
 * canonical asset — recoloured to the document's own accent and rendered to a
 * transparent PNG with headless Chrome. pdf-lib embeds PNG/JPEG only: it does
 * not accept SVG and does not rasterise, so this step is required, not optional.
 * Override the browser with CHROME_PATH if it is not in a standard location.
 */

const fs = require('fs');
const os = require('os');
const path = require('path');
const { execFileSync } = require('child_process');

const ROOT = path.join(__dirname, '..');
const CHECKLIST = path.join(ROOT, 'assets', 'CVsprings-EU-AI-Act-checklist.pdf');
const BRANDMARK_SVG = path.join(ROOT, 'public', 'brandmark.svg');

// #2440B3 is the document's own accent — the --stamp token, sampled from the
// "COMPLIANCE CHECKLIST" eyebrow (which reads #2a3fac once anti-aliased).
const MARK_COLOUR = '#2440B3';
const RASTER_PX = 512; // ~18x the 28pt draw size; keeps it crisp when zoomed

// Geometry in PDF points, measured off a 1131px render of page 1 (1.900 px/pt,
// A4). The header rule and the "2026 EDITION · JULY" line both end at x=549pt,
// and the rule sits 47.4pt from the top. A 28pt mark with its right edge on that
// same 549pt margin and its top at 60pt clears the rule by 12.6pt and sits level
// with the "COMPLIANCE CHECKLIST" eyebrow. That box was verified empty — zero
// inked pixels with 8px of padding — before it was chosen.
const MARK_SIZE = 28;
const RIGHT_MARGIN_PT = 549.0;
const TOP_PT = 60.0;

const CHROME_CANDIDATES = [
  process.env.CHROME_PATH,
  '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  '/Applications/Chromium.app/Contents/MacOS/Chromium',
  '/usr/bin/google-chrome',
  '/usr/bin/chromium',
  '/usr/bin/chromium-browser',
].filter(Boolean);

function loadPdfLib() {
  for (const id of [process.env.PDF_LIB_PATH, 'pdf-lib'].filter(Boolean)) {
    try { return require(id); } catch (_) { /* try next */ }
  }
  console.error(
    'pdf-lib not found. It is deliberately NOT a project dependency.\n' +
    'Install it transiently and point PDF_LIB_PATH at it:\n\n' +
    '  mkdir -p /tmp/pdftools && (cd /tmp/pdftools && npm init -y >/dev/null && npm i pdf-lib)\n' +
    '  PDF_LIB_PATH=/tmp/pdftools/node_modules/pdf-lib node scripts/stamp-checklist.js\n'
  );
  process.exit(1);
}

/** Rasterise public/brandmark.svg to a transparent, recoloured PNG. */
function rasteriseBrandmark() {
  const chrome = CHROME_CANDIDATES.find((p) => { try { return fs.statSync(p).isFile(); } catch (_) { return false; } });
  if (!chrome) {
    console.error(
      'No Chrome/Chromium found for rasterising the mark.\n' +
      'Set CHROME_PATH, or pass a ready-made PNG with --mark <file.png>.\n' +
      'Tried:\n  ' + CHROME_CANDIDATES.join('\n  ')
    );
    process.exit(1);
  }
  if (!fs.existsSync(BRANDMARK_SVG)) { console.error(`Missing ${BRANDMARK_SVG}`); process.exit(1); }

  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'cvs-mark-'));
  const html = path.join(tmp, 'mark.html');
  const png = path.join(tmp, 'brandmark.png');
  const svg = fs.readFileSync(BRANDMARK_SVG, 'utf8').replace(/#000\b/g, MARK_COLOUR);

  fs.writeFileSync(html,
    '<html><head><style>html,body{margin:0;padding:0;background:transparent}' +
    `svg{display:block;width:${RASTER_PX}px;height:${RASTER_PX}px}</style></head><body>${svg}</body></html>`);

  execFileSync(chrome, [
    '--headless', '--disable-gpu', '--no-sandbox', '--hide-scrollbars',
    '--default-background-color=00000000',           // transparent, not white
    `--window-size=${RASTER_PX},${RASTER_PX}`,
    `--screenshot=${png}`, `file://${html}`,
  ], { stdio: 'ignore' });

  if (!fs.existsSync(png)) { console.error('Chrome produced no PNG.'); process.exit(1); }
  console.log(`rasterised   : public/brandmark.svg -> ${RASTER_PX}px PNG, recoloured ${MARK_COLOUR}`);
  return png;
}

function arg(name) {
  const i = process.argv.indexOf(name);
  return i > -1 ? process.argv[i + 1] : null;
}
const has = (name) => process.argv.includes(name);

(async () => {
  const { PDFDocument } = loadPdfLib();

  const outPath = arg('--out') || CHECKLIST;
  const inPlace = outPath === CHECKLIST;

  if (!fs.existsSync(CHECKLIST)) { console.error(`Checklist not found: ${CHECKLIST}`); process.exit(1); }
  const srcBytes = fs.readFileSync(CHECKLIST);

  // Idempotency guard. This script is meant to be re-run after every
  // regeneration, so it WILL be pointed at an already-stamped file by mistake —
  // and stamping twice silently lays a second mark over the first. The source
  // PDF is pure vector with zero image XObjects; a stamped one has two (the PNG
  // and its alpha SMask). So any image at all means it has been stamped before.
  const alreadyStamped = /\/Subtype\s*\/Image/.test(srcBytes.toString('latin1'));
  if (alreadyStamped && !has('--force')) {
    console.error(
      'This PDF already contains an image — it looks stamped already.\n' +
      'Stamping again would draw a second mark on top of the first.\n\n' +
      'If it was regenerated from the ReportLab source and genuinely needs\n' +
      're-stamping, start from the fresh unstamped file. To override anyway:\n' +
      '  node scripts/stamp-checklist.js --force\n'
    );
    process.exit(1);
  }
  if (alreadyStamped) console.warn('WARNING: --force given; stamping an already-stamped PDF.');

  const markPath = arg('--mark') || rasteriseBrandmark();
  if (!fs.existsSync(markPath)) { console.error(`Mark PNG not found: ${markPath}`); process.exit(1); }

  const pdf = await PDFDocument.load(srcBytes);
  const png = await pdf.embedPng(fs.readFileSync(markPath));

  const pages = pdf.getPages();
  const page = pages[0]; // page 1 only
  const { width, height } = page.getSize();
  const x = RIGHT_MARGIN_PT - MARK_SIZE;
  const y = height - TOP_PT - MARK_SIZE; // pdf-lib origin is bottom-left

  page.drawImage(png, { x, y, width: MARK_SIZE, height: MARK_SIZE });

  const outBytes = await pdf.save();
  fs.writeFileSync(outPath, outBytes);

  console.log(`page size    : ${width.toFixed(2)} x ${height.toFixed(2)} pt (${pages.length} page${pages.length > 1 ? 's' : ''})`);
  console.log(`mark         : ${png.width}x${png.height} px, drawn at ${MARK_SIZE}pt`);
  console.log(`placed at    : x=${x.toFixed(1)} y=${y.toFixed(1)} (top ${TOP_PT}pt, right edge ${RIGHT_MARGIN_PT}pt)`);
  console.log(`bytes        : ${srcBytes.length} -> ${outBytes.length}`);
  console.log(`${inPlace ? 'OVERWROTE   ' : 'wrote       '}: ${outPath}`);
  if (!inPlace) console.log('\n(preview only — the served file is untouched; omit --out to write in place)');
})().catch((e) => { console.error('stamp failed:', e.message); process.exit(1); });
